exemplar.noncompliant:
// DES + ECB, and MD5 for integrity — all broken
CCCrypt(kCCEncrypt, kCCAlgorithmDES, kCCOptionECBMode,
        key, kCCKeySizeDES, NULL, plaintext, len, out, outCap, &moved);

unsigned char digest[CC_MD5_DIGEST_LENGTH];
CC_MD5(data.bytes, (CC_LONG)data.length, digest);

exemplar.compliant:
// AES-256-CBC with a random IV, SHA-256 for integrity
uint8_t iv[kCCBlockSizeAES128];
SecRandomCopyBytes(kSecRandomDefault, sizeof(iv), iv);
CCCrypt(kCCEncrypt, kCCAlgorithmAES, kCCOptionPKCS7Padding,
        key, kCCKeySizeAES256, iv, plaintext, len, out, outCap, &moved);

uint8_t digest[CC_SHA256_DIGEST_LENGTH];
CC_SHA256(data.bytes, (CC_LONG)data.length, digest);
